class CompactBindingOperationABC(ABC):
    """Source-kind behaviour owned by the mutation declaration."""

    is_import_binding = False
    is_definition_binding = False

    def pending_after(
        self, context: CompactFlowContext, binding: CompactMutation,
        pending: frozenset[CompactBindingVisit],
    ) -> frozenset[CompactBindingVisit]:
        return pending | {(context.owner_symbol, binding)}

    def validate_import_origin(self, origin: str | None) -> None:
        if origin is not None:
            raise ValueError("Only import mutations carry an imported origin")

    @abstractmethod
    def resolve_source(
        self, resolver: CompactBindingResolverABC[TargetResolutionT],
        context: CompactFlowContext, reference: LexicalValueReference,
        binding: CompactMutation, pending: frozenset[CompactBindingVisit],
    ) -> TargetResolutionT:
        raise NotImplementedError

    def resolve_definition(
        self, resolver: CompactDefinitionResolverABC[TargetResolutionT],
        symbol: str, binding: CompactMutation,
    ) -> TargetResolutionT:
        raise ValueError("Only definition mutations resolve a declaration")


class CompactValueBindingOperation(CompactBindingOperationABC):
    def resolve_source(
        self, resolver: CompactBindingResolverABC[TargetResolutionT],
        context: CompactFlowContext, reference: LexicalValueReference,
        binding: CompactMutation, pending: frozenset[CompactBindingVisit],
    ) -> TargetResolutionT:
        return resolver._possible_binding_resolution(
            context, reference, CompactFunctionTargetResolutionViolation.DYNAMIC_BINDING, pending,
        )


class CompactImportBindingOperation(CompactBindingOperationABC):
    is_import_binding = True

    def validate_import_origin(self, origin: str | None) -> None:
        pass

    def resolve_source(
        self, resolver: CompactBindingResolverABC[TargetResolutionT],
        context: CompactFlowContext, reference: LexicalValueReference,
        binding: CompactMutation, pending: frozenset[CompactBindingVisit],
    ) -> TargetResolutionT:
        origin = binding.imported_origin
        if origin is None:
            return resolver._possible_binding_resolution(
                context, reference, CompactFunctionTargetResolutionViolation.MISSING_DECLARATION, pending,
            )
        return resolver._imported_name_resolution(origin, reference.attribute_path, pending)


class CompactDefinitionBindingOperation(CompactBindingOperationABC):
    is_definition_binding = True

    def __init__(
        self,
        selector: Callable[[CompactDefinitionResolverABC[TargetResolutionT], str, CompactMutation], TargetResolutionT],
    ) -> None:
        self._selector = selector

    def pending_after(
        self, context: CompactFlowContext, binding: CompactMutation,
        pending: frozenset[CompactBindingVisit],
    ) -> frozenset[CompactBindingVisit]:
        return pending

    def resolve_source(
        self, resolver: CompactBindingResolverABC[TargetResolutionT],
        context: CompactFlowContext, reference: LexicalValueReference,
        binding: CompactMutation, pending: frozenset[CompactBindingVisit],
    ) -> TargetResolutionT:
        return resolver._definition_binding_resolution(context, reference, binding, pending)

    def resolve_definition(
        self, resolver: CompactDefinitionResolverABC[TargetResolutionT],
        symbol: str, binding: CompactMutation,
    ) -> TargetResolutionT:
        return self._selector(resolver, symbol, binding)

