class CompactDefinitionResolverABC(ABC, Generic[TargetResolutionT]):
    """Select source definitions independently of callable-use projection."""

    @abstractmethod
    def _selected_class_resolution(self, symbol: str, binding: CompactMutation) -> TargetResolutionT:
        raise NotImplementedError

    @abstractmethod
    def _selected_function_resolution(self, symbol: str, binding: CompactMutation) -> TargetResolutionT:
        raise NotImplementedError

