"""Use Python's package-boundary rules without importing analysed modules."""
if level == 0:
    return imported_module
package = self.import_name if self.is_package_init else self.import_name.rpartition(".")[0]
try:
    return resolve_name("." * level + (imported_module or ""), package)
except ImportError:
    return None
